public function avisosGlobales(): void
{
    header('Cache-Control: private, no-store, max-age=0');
    $this->validarPermiso('whatsapp.ver');
    if(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'))!=='GET')$this->responder(['ok'=>false],405);
    $uid=(int)$_SESSION['usuario_id'];
    if(session_status()===PHP_SESSION_ACTIVE)session_write_close();
    try{
        require_once __DIR__.'/../services/WhatsAppAvisosService.php';
        $modelo=new WhatsAppModel();
        $this->validarEstructura($modelo);
        $resumen=WhatsAppAvisosService::resumen($modelo->conexionParaAutorizacion(),$uid);
        $this->responder(['ok'=>true]+$resumen);
    }catch(DomainException $e){$this->responder(['ok'=>false,'mensaje'=>'Tu acceso cambió.'],403);}
    catch(Throwable $e){error_log('[whatsapp_avisos_globales] '.get_class($e));$this->responder(['ok'=>false,'mensaje'=>'No fue posible consultar WhatsApp.'],503);}
}
